<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($account['account_number']) ?> · Puihaha Electric</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f3f6fb}.topbar{background:#102a56}.panel{border:0;border-radius:20px;box-shadow:0 8px 24px #102a5610}.label{font-size:.75rem;text-transform:uppercase;letter-spacing:.08em;color:#64748b;font-weight:700}.value{font-size:1.05rem}</style></head><body><nav class="navbar topbar navbar-dark"><div class="container"><a class="navbar-brand fw-bold" href="<?= base_url('dashboard') ?>">⚡ Puihaha Electric</a><div class="d-flex gap-3 align-items-center"><span class="text-white small">Signed in as <?= esc($username) ?></span><form method="post" action="<?= base_url('logout') ?>"><button class="btn btn-outline-light btn-sm">Log out</button></form></div></div></nav><main class="container py-5" style="max-width:900px"><div class="d-flex justify-content-between align-items-center mb-3"><a href="<?= base_url('dashboard') ?>" class="text-decoration-none">← Back to accounts</a><a href="<?= base_url('account/'.$account['id'].'/edit') ?>" class="btn btn-primary">Edit account</a></div><?php if ($message = session()->getFlashdata('message')): ?><div class="alert alert-success"><?= esc($message) ?></div><?php endif; ?><div class="panel bg-white p-4 p-md-5"><div class="d-flex justify-content-between align-items-start mb-4"><div><p class="label mb-2">Customer account</p><h1 class="fw-bold mb-1"><?= esc($account['account_number']) ?></h1><p class="text-secondary mb-0"><?= esc($account['customer_name']) ?></p></div><span class="badge bg-success text-capitalize fs-6"><?= esc($account['status']) ?></span></div><div class="row g-4"><div class="col-md-6"><div class="label">Service address</div><div class="value"><?= esc($account['address']) ?></div></div><div class="col-md-6"><div class="label">Connection type</div><div class="value text-capitalize"><?= esc($account['connection_type']) ?></div></div><div class="col-md-6"><div class="label">Meter number</div><div class="value"><?= esc($account['meter_number'] ?: 'Not assigned') ?></div></div><div class="col-md-6"><div class="label">Phone</div><div class="value"><?= esc($account['phone'] ?: 'Not provided') ?></div></div><div class="col-md-6"><div class="label">Email</div><div class="value"><?= esc($account['email'] ?: 'Not provided') ?></div></div><div class="col-md-6"><div class="label">Last updated</div><div class="value"><?= esc(date('M j, Y g:i A', strtotime($account['updated_at']))) ?></div></div></div><hr class="my-4"><form method="post" action="<?= base_url('account/'.$account['id'].'/delete') ?>" onsubmit="return confirm('Delete this customer account?')"><button class="btn btn-outline-danger">Delete account</button></form></div></main></body></html>
